-- Personal departure reconstructed from Legion footage, native text/vehicle data.
-- Code-coupled: promote only with AddSC_lili_adventure in the executable.
-- The real static kite202475 and required Ramkahen arrival100571 stay native.
SET SESSION group_concat_max_len=1000000;
START TRANSACTION;
SET @lili_departure_safe := (
((SELECT COUNT(*)=7 AND SHA2(GROUP_CONCAT(SHA2(CONCAT_WS('|',COALESCE(HEX(CAST(`entryorguid` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`source_type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`id` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(IF(entryorguid=100475 AND source_type=0 AND id IN(1,6) AND link=0,IF(id=1,7,8),`link`) AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`Difficulties` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_phase_mask` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_chance` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_flags` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param1` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param2` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param3` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param4` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param5` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param1` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param2` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param3` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param4` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param5` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param6` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_param1` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_param2` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_param3` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_param4` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_x` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_y` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_z` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_o` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`comment` AS CHAR CHARACTER SET utf8mb4)),'NULL')),256) ORDER BY source_type,id SEPARATOR ','),256)='1f2cf1343174a0b38c3b2441fe4baa06878626b15421dcf45582970ab84b0d3c' FROM smart_scripts WHERE entryorguid=100475))
 AND ((SELECT COUNT(*)=5 AND SHA2(GROUP_CONCAT(SHA2(CONCAT_WS('|',COALESCE(HEX(CAST(`entryorguid` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`source_type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`id` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(IF(entryorguid=100475 AND source_type=0 AND id IN(1,6) AND link=0,IF(id=1,7,8),`link`) AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`Difficulties` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_phase_mask` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_chance` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_flags` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param1` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param2` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param3` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param4` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`event_param5` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param1` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param2` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param3` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param4` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param5` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`action_param6` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_param1` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_param2` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_param3` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_param4` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_x` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_y` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_z` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`target_o` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(`comment` AS CHAR CHARACTER SET utf8mb4)),'NULL')),256) ORDER BY source_type,id SEPARATOR ','),256)='2792706e07d8a08246f27fc015b79ff1dfe3d8e6da442e8fb9790cc571561c14' FROM smart_scripts WHERE entryorguid=100481))
 AND ((SELECT COUNT(*) FROM creature_template WHERE (entry=100475 AND AIName='SmartAI' AND ScriptName IN('','npc_lili_adventure')) OR (entry=100481 AND AIName='SmartAI' AND ScriptName='') OR (entry=100972 AND VehicleId=4518 AND AIName='' AND ScriptName IN('','npc_lili_adventure_crane')))=3)
 AND ((SELECT COUNT(*) FROM creature WHERE (guid=372111 AND id=100475 AND map=1514 AND PhaseId='5910') OR (guid=340237 AND id=100481 AND map=1514 AND PhaseId='5910 6735') OR (guid=372112 AND id=102531 AND map=1514 AND PhaseId='5906'))=3)
 AND ((SELECT COUNT(*) FROM creature_text WHERE CreatureID=100475 AND GroupID=5)=0 OR ((SELECT COUNT(*) FROM creature_text WHERE CreatureID=100475 AND GroupID=5)=1 AND (SELECT COUNT(*) FROM creature_text WHERE CreatureID=100475 AND GroupID=5 AND ID=0 AND BroadcastTextID=103341 AND Sound=62001 AND Type=12)=1))
 AND ((SELECT COUNT(*) FROM creature_text WHERE (CreatureID,GroupID,ID,BroadcastTextID,Sound,Type) IN ((100475,0,0,103325,61994,12),(100475,1,0,103327,61996,12),(100475,2,0,103335,61998,12),(100475,3,0,103339,61999,12),(100475,4,0,103340,62000,12),(100481,0,0,103329,0,16),(100481,1,0,103326,61995,12),(100481,2,0,103331,61997,12)))=8)
);
SET @lili_departure_guard := IF(@lili_departure_safe,'DO 0',
 'SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''Li Li departure source graph differs''');
PREPARE lili_departure_check FROM @lili_departure_guard;
EXECUTE lili_departure_check;
DEALLOCATE PREPARE lili_departure_check;
UPDATE creature_template SET ScriptName='npc_lili_adventure' WHERE @lili_departure_safe AND entry=100475;
UPDATE creature_template SET ScriptName='npc_lili_adventure_crane' WHERE @lili_departure_safe AND entry=100972;
-- The scoped controller now implements the actual missing movement/crane
-- continuation. Retain the original gossip and father dialogue graph.
UPDATE smart_scripts SET link=0 WHERE @lili_departure_safe AND entryorguid=100475 AND source_type=0
 AND ((id=1 AND link=7) OR (id=6 AND link=8));
INSERT INTO creature_text (CreatureID,GroupID,ID,Text,Type,Language,Probability,Emote,Duration,Sound,BroadcastTextID,MinTimer,MaxTimer,SpellID,comment)
SELECT 100475,5,0,'No, you get one now and one when we get there. No complaining!',12,0,100,0,0,62001,103341,0,0,0,'Li Li - native crane reply'
WHERE @lili_departure_safe AND NOT EXISTS(SELECT 1 FROM creature_text WHERE CreatureID=100475 AND GroupID=5);
COMMIT;
SET @lili_departure_safe := NULL;
SET @lili_departure_guard := NULL;
